#!/usr/bin/env node
// Builds a single paste-ready ES module Worker into dist/worker.js.
// The generated file is a build artifact: edit src/ and rerun this script.
import { mkdir, readFile, writeFile } from "node:fs/promises";
import { dirname, join } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const read = (file) => readFile(join(root, file));
const text = async (file) => (await read(file)).toString("utf8");
const base64 = async (file) => (await read(file)).toString("base64");

// name -> [path, kind]; kinds decide string vs binary at runtime.
const ASSETS = [
  ["CLIENT_HTML", "src/client.html", "text"],
  ["QRCODE_SRC", "src/qrcode.txt", "text"],
  ["FAVICON_SVG", "src/favicon.txt", "text"],
  ["FONT_WOFF2", "src/fonts/jetbrains-mono-latin-400.woff2", "bytes"],
  ["FAVICON_32", "src/favicon-32.png", "bytes"],
  ["FAVICON_180", "src/favicon-180.png", "bytes"],
];

let source = await text("src/index.js");

for (const [name, file] of ASSETS) {
  const spec = `./${file.replace(/^src\//, "")}`;
  const re = new RegExp(`^import ${name} from "${spec}";\\r?\\n`, "m");
  if (!re.test(source)) {
    throw new Error(`expected "import ${name} from '${spec}'" in src/index.js`);
  }
  source = source.replace(re, "");
}

const constImport = source.match(/import \{([\s\S]*?)\} from "\.\/protocol\.js";\r?\n/);
if (!constImport) throw new Error('expected the protocol.js constant import in src/index.js');
const names = constImport[1]
  .split(",")
  .map((name) => name.trim())
  .filter(Boolean);
source = source.replace(constImport[0], "");

if (/^import\s/m.test(source)) throw new Error("unresolved import left in src/index.js");

const protocol = await import(pathToFileURL(join(root, "src/protocol.js")).href);
const constants = names
  .map((name) => {
    if (!(name in protocol)) throw new Error(`protocol.js does not export ${name}`);
    return `const ${name} = ${JSON.stringify(protocol[name])};`;
  })
  .join("\n");

const assetLines = [];
for (const [name, file, kind] of ASSETS) {
  const encoded = await base64(file);
  const decode = kind === "text" ? "b64text" : "b64bytes";
  assetLines.push(`const ${name} = ${decode}(\n  "${encoded}",\n);`);
}

const header = `// relay-min — single-file build. Generated by scripts/build-single.mjs.
// Deploy: Cloudflare Dashboard -> Workers & Pages -> Create -> Worker,
// paste this file, then add a Durable Object binding named RELAY_ROOM
// bound to class RelayRoom. Do not edit this file; edit src/ and rebuild.
`;

const helpers = `const b64bytes = (s) => Uint8Array.from(atob(s), (c) => c.charCodeAt(0));
const b64text = (s) => new TextDecoder().decode(b64bytes(s));`;

const output = [header, helpers, constants, ...assetLines, "", source].join("\n");
await mkdir(join(root, "dist"), { recursive: true });
await writeFile(join(root, "dist", "worker.js"), output);

// Local verification only: lets `wrangler dev --config dist/wrangler.toml` run
// the generated file with the same binding as the dashboard setup.
const distConfig = `name = "relay-min-single"
main = "worker.js"
compatibility_date = "2026-10-19"
workers_dev = true

[observability]
enabled = true

[[durable_objects.bindings]]
name = "RELAY_ROOM"
class_name = "RelayRoom"

[[migrations]]
tag = "v1"
new_sqlite_classes = ["RelayRoom"]
`;
await writeFile(join(root, "dist", "wrangler.toml"), distConfig);

const bytes = Buffer.byteLength(output, "utf8");
console.log(`dist/worker.js  ${(bytes / 1024).toFixed(1)} KiB`);
console.log(`  assets: ${ASSETS.map(([name]) => name).join(", ")}`);
console.log(`  constants: ${names.length}`);
